<x-layouts.app :heading="$product->exists ? 'Edit product' : 'New product'"><form class="panel form-grid" method="post" action="{{ $product->exists ? route('products.update',$product) : route('products.store') }}">@csrf @if($product->exists)@method('PUT')@endif<label>Product code<input name="code" value="{{ old('code',$product->code) }}" required></label><label>Product name<input name="name" value="{{ old('name',$product->name) }}" required></label><label>Category<select name="category_id"><option value="">Uncategorized</option>@foreach($categories as $category)<option value="{{ $category->id }}" @selected(old('category_id',$product->category_id)==$category->id)>{{ $category->name }}</option>@endforeach</select></label><label>Unit<input name="unit" value="{{ old('unit',$product->unit ?? 'EA') }}" required></label><label>Minimum stock<input type="number" step=".001" min="0" name="minimum_stock" value="{{ old('minimum_stock',$product->minimum_stock ?? 0) }}" required></label><label>Maximum stock<input type="number" step=".001" min="0" name="maximum_stock" value="{{ old('maximum_stock',$product->maximum_stock) }}"></label><label>Status<select name="status"><option value="ACTIVE" @selected(old('status',$product->status)==='ACTIVE')>Active</option><option value="INACTIVE" @selected(old('status',$product->status)==='INACTIVE')>Inactive</option></select></label><label class="wide">Description<textarea name="description" rows="4">{{ old('description',$product->description) }}</textarea></label><div class="wide form-actions"><a class="btn" href="{{ route('products.index') }}">Cancel</a><button class="btn primary">Save product</button></div></form></x-layouts.app>
